// Original slow ambient harmony: no music-box lead or rapid repeating melody.
export function createShopMusic(){let ctx,master,filter,timer,next=0,bar=0,enabled=false;const chords=[[48,55,59,64],[45,52,55,60],[41,48,52,57],[43,50,55,59]];
 function voice(note,time,duration,volume,pan){const gain=ctx.createGain(),p=ctx.createStereoPanner();p.pan.value=pan;gain.gain.setValueAtTime(0,time);gain.gain.linearRampToValueAtTime(volume,time+2.2);gain.gain.setTargetAtTime(.0001,time+duration-3,1);gain.connect(p);p.connect(filter);for(const detune of [-3,3]){const osc=ctx.createOscillator();osc.type='sine';osc.frequency.value=440*2**((note-69)/12);osc.detune.value=detune;osc.connect(gain);osc.start(time);osc.stop(time+duration+1)} }
 function schedule(){if(!enabled||ctx.state!=='running')return;while(next<ctx.currentTime+.4){const chord=chords[bar++%chords.length];chord.forEach((n,i)=>voice(n,next+i*.17,11,.024,[-.35,.25,-.15,.35][i]));next+=8;}}
 async function set(on){enabled=!!on;document.body.dataset.music=on?'starting':'off';if(!on){clearInterval(timer);timer=null;if(ctx)await ctx.suspend();return}try{if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.gain.value=.36;filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1300;filter.Q.value=.5;filter.connect(master);master.connect(ctx.destination)}await ctx.resume();if(!enabled)return;document.body.dataset.music='playing';next=Math.max(next,ctx.currentTime+.1);clearInterval(timer);timer=setInterval(schedule,180);schedule()}catch{document.body.dataset.music='unavailable';enabled=false}}
 document.addEventListener('visibilitychange',()=>{if(!ctx)return;if(document.hidden)ctx.suspend();else if(enabled)ctx.resume()});window.addEventListener('pagehide',()=>{clearInterval(timer);ctx?.close()});return {set};}
